import sys
import json
import numpy as np
import pandas as pd

def to_float(x, nd=2):
    return float(round(float(x), nd))

def main():
    path = sys.argv[1]
    df = pd.read_csv(path)

    facts = []

    # ---- TOTALS: Revenue ----
    rev_tw = df['Revenue_TW'].sum(skipna=True)
    rev_lw = df['Revenue_LW'].sum(skipna=True)
    rev_ly = df['Revenue_LY'].sum(skipna=True)

    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "TW",
        "value": to_float(rev_tw), "formula": "sum(Revenue_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LW",
        "value": to_float(rev_lw), "formula": "sum(Revenue_LW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LY",
        "value": to_float(rev_ly), "formula": "sum(Revenue_LY)"
    })

    # ---- TOTALS: Units ----
    units_tw = df['Units_TW'].sum(skipna=True)
    units_lw = df['Units_LW'].sum(skipna=True)
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "TW",
        "value": to_float(units_tw, 0), "formula": "sum(Units_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "LW",
        "value": to_float(units_lw, 0), "formula": "sum(Units_LW)"
    })

    # ---- TOTALS: Orders ----
    orders_tw = df['Orders_TW'].sum(skipna=True)
    orders_lw = df['Orders_LW'].sum(skipna=True)
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "TW",
        "value": to_float(orders_tw, 0), "formula": "sum(Orders_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "LW",
        "value": to_float(orders_lw, 0), "formula": "sum(Orders_LW)"
    })

    # ---- TOTAL WoW% ----
    if rev_lw and not np.isnan(rev_lw) and rev_lw != 0:
        total_wow = (rev_tw - rev_lw) / rev_lw * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "WoW",
            "value": to_float(total_wow, 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100"
        })

    # ---- TOTAL YoY% ----
    if rev_ly and not np.isnan(rev_ly) and rev_ly != 0:
        total_yoy = (rev_tw - rev_ly) / rev_ly * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "YoY",
            "value": to_float(total_yoy, 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100"
        })

    # ---- Top 4 entities by Revenue_TW ----
    top_rev = df.dropna(subset=['Revenue_TW']).sort_values('Revenue_TW', ascending=False).head(4)
    for _, row in top_rev.iterrows():
        facts.append({
            "entity": str(row['Entity']), "metric": "revenue", "period": "TW",
            "value": to_float(row['Revenue_TW']), "formula": "Revenue_TW"
        })

    # ---- Top 3 WoW gainers ----
    wow_df = df.dropna(subset=['WoW_Pct'])
    top_wow_gain = wow_df.sort_values('WoW_Pct', ascending=False).head(3)
    for _, row in top_wow_gain.iterrows():
        facts.append({
            "entity": str(row['Entity']), "metric": "revenue", "period": "WoW",
            "value": to_float(row['WoW_Pct'], 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })

    # ---- Top 3 WoW decliners ----
    top_wow_decline = wow_df.sort_values('WoW_Pct', ascending=True).head(3)
    for _, row in top_wow_decline.iterrows():
        facts.append({
            "entity": str(row['Entity']), "metric": "revenue", "period": "WoW",
            "value": to_float(row['WoW_Pct'], 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })

    # ---- Top 3 YoY gainers ----
    yoy_df = df.dropna(subset=['YoY_Pct'])
    top_yoy_gain = yoy_df.sort_values('YoY_Pct', ascending=False).head(3)
    for _, row in top_yoy_gain.iterrows():
        facts.append({
            "entity": str(row['Entity']), "metric": "revenue", "period": "YoY",
            "value": to_float(row['YoY_Pct'], 1),
            "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
        })

    # ---- Top 3 YoY decliners ----
    top_yoy_decline = yoy_df.sort_values('YoY_Pct', ascending=True).head(3)
    for _, row in top_yoy_decline.iterrows():
        facts.append({
            "entity": str(row['Entity']), "metric": "revenue", "period": "YoY",
            "value": to_float(row['YoY_Pct'], 1),
            "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
        })

    # Trim to 25 facts max
    facts = facts[:25]

    print(json.dumps(facts))

if __name__ == "__main__":
    main()
